 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { Link } from 'react-router-dom'

export default function PredictionCard({ prediction, onRefresh, currentUser }) {
    const [isLiked, setIsLiked] = useState(false)
    const [likesCount, setLikesCount] = useState(prediction.likes_count || 0)
    const [liking, setLiking] = useState(false)

    useEffect(() => {
        if (currentUser) {
            checkLikeStatus()
        }
    }, [prediction.id, currentUser])

    const checkLikeStatus = async () => {
        try {
            const { data, error } = await supabase
                .from('public_prediction_likes')
                .select('id')
                .eq('prediction_id', prediction.id)
                .eq('user_id', currentUser.id)
                .maybeSingle()

            if (error) {
                console.error('Error checking like status:', error)
                return
            }
            setIsLiked(!!data)
        } catch (error) {
            console.error('Error in checkLikeStatus:', error)
        }
    }

    const handleLike = async () => {
        if (!currentUser) {
            alert('Please sign in to like')
            return
        }
        if (liking) return
        setLiking(true)

        try {
            console.log('Liking prediction:', prediction.id, 'Current likes:', likesCount, 'isLiked:', isLiked)

            if (isLiked) {
                // Unlike
                const { error: deleteError } = await supabase
                    .from('public_prediction_likes')
                    .delete()
                    .eq('prediction_id', prediction.id)
                    .eq('user_id', currentUser.id)

                if (deleteError) {
                    console.error('Delete error:', deleteError)
                    throw deleteError
                }

                const { error: updateError } = await supabase
                    .from('public_predictions')
                    .update({ likes_count: Math.max(0, likesCount - 1) })
                    .eq('id', prediction.id)

                if (updateError) {
                    console.error('Update error:', updateError)
                    throw updateError
                }

                setIsLiked(false)
                setLikesCount(prev => prev - 1)
                console.log('Unliked successfully')

            } else {
                // Like
                const { error: insertError } = await supabase
                    .from('public_prediction_likes')
                    .insert({
                        prediction_id: prediction.id,
                        user_id: currentUser.id
                    })

                if (insertError) {
                    console.error('Insert error:', insertError)
                    throw insertError
                }

                const { error: updateError } = await supabase
                    .from('public_predictions')
                    .update({ likes_count: likesCount + 1 })
                    .eq('id', prediction.id)

                if (updateError) {
                    console.error('Update error:', updateError)
                    throw updateError
                }

                setIsLiked(true)
                setLikesCount(prev => prev + 1)
                console.log('Liked successfully')
            }

            if (onRefresh) onRefresh()
        } catch (error) {
            console.error('Error in handleLike:', error)
            alert('Failed to like prediction. Please try again.')
        } finally {
            setLiking(false)
        }
    }

    const data = prediction.prediction_data || {}
    let resultEmoji = '🤝'
    if (data.result === 'Home Win') resultEmoji = '🏠'
    else if (data.result === 'Away Win') resultEmoji = '✈️'

    return (
        <div className="bg-white rounded-xl shadow-md p-4 hover:shadow-lg transition">
            <div className="flex items-center gap-3 mb-3">
                <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold">
                    {prediction.profiles?.username?.[0]?.toUpperCase() || 'U'}
                </div>
                <div>
                    <div className="font-semibold">
                        {prediction.profiles?.full_name || prediction.profiles?.username || 'Unknown'}
                    </div>
                    <div className="text-sm text-gray-500">
                        @{prediction.profiles?.username || 'user'} • {prediction.profiles?.points || 0} pts
                    </div>
                </div>
            </div>

            <div className="bg-gray-50 rounded-lg p-3 mb-3">
                <div className="flex items-center justify-between">
                    <span className="text-lg">{resultEmoji}</span>
                    <span className="font-bold">{data.result || 'Draw'}</span>
                    <span className="text-sm text-gray-500">🟨{data.yellowCards || 0} 🟥{data.redCards || 0}</span>
                    <span className="text-sm text-gray-500">🏁{data.corners || 0} 🚩{data.offsides || 0}</span>
                </div>
                <div className="text-xs text-gray-400 text-center mt-1">
                    🌍 Public Prediction
                </div>
            </div>

            <div className="flex items-center justify-between text-sm">
                <button
                    onClick={handleLike}
                    disabled={liking}
                    className={`flex items-center gap-1 transition ${isLiked ? 'text-red-500' : 'text-gray-400 hover:text-red-500'}`}
                >
                    {isLiked ? '❤️' : '🤍'} {likesCount}
                </button>
                <span className="text-gray-400">{new Date(prediction.created_at).toLocaleDateString()}</span>
            </div>
        </div>
    )
}
